goal: IsDecompOn.of_leftInvOn {f g : X → X} {A : Set X} {S : Finset G}
    (hf : IsDecompOn f A S) (h : LeftInvOn g f A) : IsDecompOn g (f '' A) S⁻¹
premises: rintro, rcases, Finset.inv_mem_inv, inv_smul_smul, symm, simps, toPartialEquiv

goal: smul_set_iInter {ι : Sort*}
    (a : α) (t : ι → Set β) : (a • ⋂ i, t i) = ⋂ i, a • t i
premises: image_iInter, MulAction.bijective, to_additive

goal:
IsPretransitive.of_orbit {X : Type*} [Group G] [MulAction G X] {x₀ : X}
    (ha : ∀ x, ∃ g : G, g • x₀ = x) :
    IsPretransitive G X

multiplicative_of_total (p : α → Prop) (hswap : ∀ {a b}, p a → p b → f a b * f b a = 1)
    (hmul : ∀ {a b c}, r a b → r b c → p a → p b → p c → f a c = f a b * f b c) {a b c : α}
    (pa : p a) (pb : p b) (pc : p c) : f a c = f a b * f b c

centralizer_prod {N : Type*} [Mul N] {S : Set M} {T : Set N}
    (hS : S.Nonempty) (hT : T.Nonempty) :
    (S ×ˢ T).centralizer = S.centralizer ×ˢ T.centralizer
